const client={auth:{getUser:async()=>({data:{user:{id:'preview'}}})},from(table){let ids=null,values=null;const q={select(){return q},eq(){return q},is(){return q},order(){return q},limit(){return q},in(_,v){ids=v;return q},update(v){values=v;return q},single(){return q},then(resolve){if(values&&table==='user_notifications')notices=notices.filter(n=>!ids.includes(n.id));return Promise.resolve({data:table==='profiles'?{username,display_name:'Marie',discovery_visibility:'everyone',avatar_url:null}:notices,count:notices.length}).then(resolve)}};return q},async rpc(name,{p_action,p_data,p_handle}={}){if(name==='nailmoods_handle_available')return{data:true};if(name==='set_nailmoods_identity'){username=p_handle;return{data:true}}if(p_action==='list')return{data:rows};if(p_action==='history')return{data:{messages}};if(p_action==='read'){rows[0].unread=0;notices=notices.filter(n=>n.kind!=='message');return{data:{ok:true}}}if(p_action==='send'){messages.unshift({id:'demo-'+Date.now(),body:p_data.body,created_at:new Date().toISOString(),mine:true});return{data:{ok:true}}}if(p_action==='accept'){rows=rows.map(r=>r.id===p_data.id?{...r,status:'accepted'}:r);return{data:{ok:true}}}return{data:[]}}};
